  'nx.plat.ruNotSaved': 'That value was not recorded.',
  'nx.plat.ruBlockedTitle': 'Legal values nobody has read yet',
  'nx.plat.ruBlockedDesc': 'Each of these is a figure the product refuses to guess and nobody has checked. Some close a market to new clients; the rest refuse one capability and leave everything else trading.',
  'nx.plat.ruBlockedCount': '{count} unchecked',
  // Each blocking rule, named, with what is still missing from it. A count
  // told an operator a market was closed and nothing about how to open it.
  'nx.plat.ruBlockedWhat': 'What is required',
  'nx.plat.ruBlockedFields': 'Still unfilled: {fields}',
  'nx.plat.ruBlockedNoFields': 'The value has never been recorded.',
  'nx.plat.ruBlockedSource': 'From: {document}',
  'nx.plat.ruBlockedOpen': 'Open the source',
  'nx.plat.ruBlockedWhy': 'RawSyst cannot supply this. It is a figure published by the authority named above, and recording it is a person putting their name to having read it there. Inventing one would compute a legal amount from a guess.',
  'nx.plat.ruBlockedAfter': 'Once recorded and marked checked: the market opens for new clients, the value resolves at the date of every document processed, and the correction supersedes rather than overwrites — so re-running an earlier month still gives that month\u2019s answer.',
  'nx.plat.ruBlockedRecord': 'Record this value',
  'nx.plat.ruBlockedProduction': 'A production deployment serving this market refuses to start while this is unchecked, and every use of the value is refused meanwhile. Neither is weakened by recording it here; both are satisfied by it.',
  'nx.plat.ruAwaitingDesc': '{count} of these do not close any market. The capability that needs the figure refuses by name where somebody asks for it, and the rest of the product trades normally.',
  'nx.plat.ruBlocksOnboarding': 'Closes the market',
  'nx.plat.ruBlocksFeature': 'One capability',
  'nx.plat.ruAwaitingAfter': 'Once recorded and marked checked: the capability computes, the value resolves at the date of every document processed, and the correction supersedes rather than overwrites — so re-running an earlier month still gives that month’s answer.',
  'nx.plat.ruAwaitingProduction': 'A production deployment serving this market starts normally while this is unchecked. What is missing is a figure published elsewhere, not a piece of this product: the software that computes with it is built and tested, and it refuses by name until the figure is on record.',
  'nx.plat.ruNotDescribed': 'This product does not hold a description of where these figures come from, so they are recorded as a payload rather than as labelled boxes.',
  'nx.plat.ruSoftwareIsBuilt': 'Everything that consumes these values is built, reachable and tested. Recording a value here is the whole of what is required; no release, migration or code change follows it.',
  'nx.plat.ruBlocksLabel': 'What it blocks while unchecked',
  'nx.plat.ruBlocksHint': 'An end-of-service band is computed when somebody leaves, so it need not stop a shop opening. A tax format is needed by the first sale, so it must.',
  'nx.plat.ruBlocksFeatureOpt': 'One capability, where it is used',
  'nx.plat.ruBlocksOnboardingOpt': 'The whole market, to new clients',
