  // --- Backup & Recovery, the platform operator's screen (nx.pbk) -----------
  //
  // The vocabulary this subsystem lives or dies by is in two of these keys.
  // `phase.uploaded` is "Not checked yet" and NOT "Backed up"; `phase.verified`
  // is "Proved to restore", and it is only ever shown for a snapshot that has
  // been restored into a temporary database and compared against its own
  // manifest. A translation that made those two read alike would undo the whole
  // thing.
  'nx.pbk.title': "Backup & Recovery",
